153:     private List<JSONObject> buildData(AbstractCLYPubBillHelper helper, JSONArray returnData) {
154:         List<AbstractCLYBuildDataService> service = helper.getBuildServices();
155:         int dataSize = returnData.size();
156:         int serviceSize = service.size();
157:         // 数据提取
158:         for (int i = 0; i < dataSize; i++) {
159:             JSONObject record = returnData.getJSONObject(i);
160:             for (int j = 0; j < serviceSize; j++) {
161:                 service.get(j).addData(record);
162:             }
163:         }
164:         // 数据构建
165:         for (int i = 0; i < serviceSize; i++) {
166:             service.get(i).buildData();
167:         }
168:         // 数据设置、分类、构造结果
169:         AbstractCLYPublicClassifyService classifyService = helper.getClassifyService();
170:         for (int i = 0; i < dataSize; i++) {
171:             JSONObject record = returnData.getJSONObject(i);
172:             for (int j = 0; j < serviceSize; j++) {
173:                 service.get(j).setData(record);
174:             }
175:             classifyService.rowProcess(record);
176:         }
177:         return sort(classifyService.getMapResult());
178:     }
