21f5a54304 差旅云：差旅云多语言优化/法务迁移zh

diff --git a/code/cmhk/8b4t-cmhk-zh/src/main/java/kd/cmhk/api/cly/util/CLYEnvironmentUtil.java b/code/cmhk/8b4t-cmhk-zh/src/main/java/kd/cmhk/api/cly/util/CLYEnvironmentUtil.java
index 59d7d225c2..796567d6cb 100644
--- a/code/cmhk/8b4t-cmhk-zh/src/main/java/kd/cmhk/api/cly/util/CLYEnvironmentUtil.java
+++ b/code/cmhk/8b4t-cmhk-zh/src/main/java/kd/cmhk/api/cly/util/CLYEnvironmentUtil.java
@@ -374,125 +374,125 @@ public class CLYEnvironmentUtil {
     public static void setAss(IDataModel model, List<Integer> indexs, List<String> sqdhs, List<Object> fyxms, List<String> xmids,
             List<String> xmTypes) {
         StringBuilder typeNots = new StringBuilder();
         StringBuilder xmNulls = new StringBuilder();
         StringBuilder cosNulls = new StringBuilder();
         StringBuilder xmDataNulls = new StringBuilder();
         if (!indexs.isEmpty()) {
 
             List<String> actFields = new ArrayList<>(Arrays.asList(CommonUtil.getStdConfig("assttypelist").split("#")));
 
             Map<String, String> actFieldMap = new HashMap<>();
             DynamicObjectCollection actFieldCol = QueryServiceHelper.query("8b4t_costitemassttypemap", "number,assttypeno",
                     new QFilter[]{
                             new QFilter("number", QCP.in, actFields), new QFilter("assttypeno", QCP.in, xmTypes)
                     });
             for (int i = 0, size = actFieldCol.size(); i < size; i++) {
                 DynamicObject actFieldData = actFieldCol.get(i);
                 actFieldMap.put(actFieldData.getString("assttypeno"), actFieldData.getString("number"));
             }
 
             Map<String, DynamicObject> xmTypeMap = new HashMap<>();
             DynamicObject[] xmTypeBills = BusinessDataServiceHelper.load("bd_asstacttype", "id,number,name",
                     new QFilter[]{new QFilter("number", QCP.in, xmTypes)});
             for (int i = 0; i < xmTypeBills.length; i++) {
                 xmTypeMap.put(xmTypeBills[i].getString("number"), xmTypeBills[i]);
             }
 
             long orgId = ((DynamicObject) model.getValue("company")).getLong("id");
             boolean isJKJK = BizLogicParamUtil.isControlNotLink(orgId, BizLogicParamUtil.ZSJKJK);
             Map<String, DynamicObject> xmDataMap = new HashMap<>();
             List<Long> orgIds = OrgUnitServiceHelper.getAllSuperiorOrgs(OrgViewType.OrgUnit, orgId);
             orgIds.add(orgId);
             if (isJKJK) {
                 DynamicObject[] details = BusinessDataServiceHelper.load("bos_assistantdata_detail",
                         "id,number,name,cmhk_itemprops,group,cmhk_projectnumber", new QFilter[]{
                                 new QFilter("createorg", QCP.in, orgIds), new QFilter("group.number", QCP.equals, "3004"),
                                 new QFilter("cmhk_projectnumber", QCP.in, xmids)
                         }, "group.number,cmhk_projectnumber,createorg asc");
                 for (int i = 0; i < details.length; i++) {
                     xmDataMap.put("3004" + details[i].getString("cmhk_projectnumber"), details[i]);
                 }
             }
             DynamicObject[] details = BusinessDataServiceHelper.load("bos_assistantdata_detail",
                     "id,number,name,cmhk_itemprops,group", new QFilter[]{
                             new QFilter("createorg", QCP.in, orgIds), new QFilter("group.number", QCP.in, xmTypes),
                             new QFilter("number", QCP.in, xmids)
                     }, "group.number,number,createorg asc");
             for (int i = 0; i < details.length; i++) {
                 String groupNumber = details[i].getDynamicObject("group").getString("number");
                 String key = groupNumber + details[i].getString("number");
                 if ("3004".equals(groupNumber)) {
                     if (!xmDataMap.containsKey(key)) {
                         xmDataMap.put(key, details[i]);
                     }
                 } else {
                     xmDataMap.put(key, details[i]);
                 }
             }
 
             orgIds = OrgUnitServiceHelper.getAllSuperiorOrgs(OrgViewType.Accounting, orgId);
             orgIds.add(orgId);
             String deptType = ((DynamicObject) model.getValue("costdept")).getString("departmenttype");
             QFilter filter = new QFilter("entryentity.company", QCP.in, orgIds).and("entryentity.departmenttype", QCP.equals,
                     deptType == null ? "" : deptType);
 
             boolean isZH = model.getDataEntityType().getName().endsWith("_zh");
 
             for (int i = 0; i < xmTypes.size(); i++) {
                 String xmTypeNum = xmTypes.get(i);
                 String fieldKey = actFieldMap.get(xmTypeNum);
                 DynamicObject xmType = xmTypeMap.get(xmTypeNum);
                 if (fieldKey == null) {
                     typeNots.append(",").append(xmTypeNum);
                 } else if (xmType == null) {
                     xmNulls.append(",").append(xmTypeNum);
                 } else {
                     if (QueryServiceHelper.exists("8b4t_costitem_asstacttype", new QFilter[]{
                             new QFilter("costitem", QCP.equals, fyxms.get(i)), filter,
                             new QFilter("entryentity.projecttype", QCP.equals, xmType.get("id"))
                     })) {
                         String xmid = xmids.get(i);
                         DynamicObject xmData = xmDataMap.get(xmType.getString("number") + xmid);
                         if (xmData == null) {
                             xmDataNulls.append(",").append(sqdhs.get(i));
                         } else {
                             int index = indexs.get(i);
                             model.setValue("isitemexpense", true, index);
                             model.setValue("cmhk_projecttype", xmType, index);
                             model.setValue(fieldKey, xmData, index);
                             if (isZH) {
                                 model.setValue("cmhk_itemprops", xmData.get("cmhk_itemprops"), index);
                             }
                             model.setValue("asstacttype", xmData.get("name"), index);
                         }
                     } else {
                         cosNulls.append(",").append(sqdhs.get(i));
                     }
                 }
             }
         }
