162:             DBRoute sys = new DBRoute("sys");
163:             DynamicObjectResultSetCallback callBacksys = new DynamicObjectResultSetCallback<>();
164:             //in直接传List会有[],导致sql查询失败,需要转换成字符串用逗号隔开
165:             String result = rete.stream().map(String::valueOf).collect(Collectors.joining(","));
166:             String ksqlsys = "SELECT fnumber FROM t_ORG_ORG WHERE FID IN(" + result + ") ";
