168:             if (collectionsys != null && collectionsys.size() > 0) {
169:                 for (DynamicObject dynamicObject : collectionsys) {
170:                     String fnumber = dynamicObject.getString("fnumber");
171:                     organization.add(fnumber);
172:                 }
173:             }
174:         }
175:         return organization;
